face.layout_source:
// jupiter-8.face: the panel for tap/examples/synths/poly/jupiter-8.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/synths/poly/jupiter-8.face --meta <graph>.cragmeta

face "Jupiter-8" {
  row(gap = 10) {
    box "LFO" { knob "Rate" (lfo_rate) knob "Delay" (lfo_delay) selector "Wave" (lfo_shape) }
    box "VCO Modulator" (grow = 1) {
      knob "LFO" (vco_lfo) knob "Env" (vco_env) selector "To" (vco_mod_to) knob "PW" (pulse_width)
      knob "PWM LFO" (pwm_lfo) knob "PWM Env" (pwm_env)
    }
    box "VCO 1" { knob "Range" (vco1_octave) selector "Wave" (vco1_shape) knob "X-Mod" (cross_mod) }
  }
  row(gap = 10) {
    box "VCO 2" { toggle "Sync" (sync) knob "Range" (vco2_octave) knob "Fine" (vco2_tune) selector "Wave" (vco2_shape) }
    box "Mix" { knob "1 / 2" (vco_mix) }
    box "HPF" { knob "Cutoff" (hpf_cutoff) }
    box "VCF" (grow = 1) {
      knob.big "Cutoff" (cutoff) knob "Res" (resonance) toggle "24 dB" (slope_24db) knob "Env" (vcf_env)
      selector "Source" (vcf_env_source) knob "LFO" (vcf_lfo) knob "Key" (key_follow)
    }
  }
  row(gap = 10) {
    box "ENV 1" { adsr(env1_attack, env1_decay, env1_sustain, env1_release) }
    box "ENV 2" { adsr(env2_attack, env2_decay, env2_sustain, env2_release) }
    box "VCA" { knob "LFO" (vca_lfo) knob "Velocity" (velocity_amount) }
    box "Output" (grow = 1) { knob "Spread" (pan_spread) knob.big "Volume" (volume) viz(grow = 1) }
  }
  keys(note_on, note_off)
}
